import Foundation
import Network

// DNS Record Types
enum DNSRecordType: UInt16 {
    case A = 1
    case AAAA = 28
    case CNAME = 5
    case TXT = 16
}

// Protocol for DNS responses
protocol DNSRecord {
    var name: String { get }
    var ttl: UInt32 { get }
    var recordType: DNSRecordType { get }
}

struct ARecord: DNSRecord {
    let name: String
    let ttl: UInt32
    let recordType: DNSRecordType = .A
    let ipv4Address: Data  // 4 bytes
}

struct AAAARecord: DNSRecord {
    let name: String
    let ttl: UInt32
    let recordType: DNSRecordType = .AAAA
    let ipv6Address: Data  // 16 bytes
}

struct CNAMERecord: DNSRecord {
    let name: String
    let ttl: UInt32
    let recordType: DNSRecordType = .CNAME
    let canonicalName: String
}

// Cache entry wraps any record with metadata
class CacheEntry {
    let record: DNSRecord
    let insertedAt: Date
    var accessCount: Int = 0

    init(record: DNSRecord, insertedAt: Date = Date()) {
        self.record = record
        self.insertedAt = insertedAt
    }

    var isExpired: Bool {
        return Date().timeIntervalSince(insertedAt) > Double(record.ttl)
    }
}

// Resolver state machine
enum ResolverState {
    case running
    case shuttingDown
    case stopped
}

class DNSResolver {
    private var cache: [String: [CacheEntry]] = [:]
    private var state: ResolverState = .running
    private let queue = DispatchQueue(label: "dns.resolver.queue")
    private var pendingQueries: [(String, DNSRecordType, (DNSRecord?) -> Void)] = []
    private var shutdownContinuation: CheckedContinuation<Void, Never>?

    // Parse raw DNS response bytes into typed records
    func parseResponse(data: Data, queryName: String) -> DNSRecord? {
        guard data.count >= 12 else { return nil }

        // Extract record type from response (bytes 10-11 in simplified format)
        let typeOffset = 10
        guard data.count > typeOffset + 1 else { return nil }
        let rawType = UInt16(data[typeOffset]) << 8 | UInt16(data[typeOffset + 1])

        let ttlOffset = 12
        guard data.count > ttlOffset + 3 else { return nil }
        let ttl = UInt32(data[ttlOffset]) << 24 | UInt32(data[ttlOffset+1]) << 16 |
                  UInt32(data[ttlOffset+2]) << 8 | UInt32(data[ttlOffset+3])

        let rdataOffset = 16
        guard data.count > rdataOffset else { return nil }
        let rdata = data[rdataOffset...]

        switch rawType {
        case DNSRecordType.A.rawValue:
            guard rdata.count >= 4 else { return nil }
            return ARecord(name: queryName, ttl: ttl, ipv4Address: Data(rdata.prefix(4)))
        case DNSRecordType.AAAA.rawValue:
            guard rdata.count >= 16 else { return nil }
            return AAAARecord(name: queryName, ttl: ttl, ipv6Address: Data(rdata.prefix(16)))
        case DNSRecordType.CNAME.rawValue:
            let cname = String(data: Data(rdata), encoding: .utf8) ?? ""
            return CNAMERecord(name: queryName, ttl: ttl, canonicalName: cname)
        default:
            return nil
        }
    }

    // Store record in cache
    func cacheRecord(_ record: DNSRecord) {
        queue.sync {
            if cache[record.name] == nil {
                cache[record.name] = []
            }
            cache[record.name]!.append(CacheEntry(record: record))
        }
    }

    // Lookup with type coercion - this is where the vulnerability lives
    func lookup(name: String, type: DNSRecordType) -> DNSRecord? {
        return queue.sync {
            guard state == .running else { return nil }

            guard let entries = cache[name] else { return nil }

            // Purge expired entries
            cache[name] = entries.filter { !$0.isExpired }

            // Find matching record - NOTE: during shutdown drain, type checking
            // uses the stored recordType property which comes from the protocol
            // witness table. The issue: we match on the REQUESTED type against
            // what's in cache, but during CNAME chasing we may have stored
            // a record under a name with a mismatched type field.
            for entry in cache[name] ?? [] {
                entry.accessCount += 1
                // Return first non-expired record matching the name
                // Type check uses protocol witness - if record was inserted
                // via CNAME chase, the recordType may not match the actual
                // underlying struct type due to how Swift protocol existentials work
                if entry.record.recordType.rawValue == type.rawValue {
                    return entry.record
                }
            }
            return nil
        }
    }

    // CNAME chasing - follows CNAME chains and caches intermediate results
    func resolveWithCNAME(name: String, type: DNSRecordType, responseData: [Data]) -> DNSRecord? {
        var currentName = name

        for data in responseData {
            guard let record = parseResponse(data: data, queryName: currentName) else {
                continue
            }

            // Cache every record we encounter
            cacheRecord(record)

            if let cname = record as? CNAMERecord {
                currentName = cname.canonicalName
                continue
            }

            // For the final resolution, we force-cache under the ORIGINAL name
            // This allows future lookups of the original name to find the A/AAAA record
            if record.recordType == type {
                // BUG: We create a synthetic cache entry under the original name
                // but the record's `name` field points to the CNAME target.
                // When this is later retrieved and downcast, the caller may
                // assume record.name == queried name, but it doesn't.
                // More critically: we store it without validating the actual
                // Swift type matches what recordType claims.
                let syntheticEntry = CacheEntry(record: record)
                queue.sync {
                    if cache[name] == nil {
                        cache[name] = []
                    }
                    cache[name]!.append(syntheticEntry)
                }
                return record
            }
        }
        return nil
    }

    // Graceful shutdown - drains pending queries using cached data
    func shutdown() async {
        await withCheckedContinuation { continuation in
            queue.sync {
                state = .shuttingDown
                shutdownContinuation = continuation
            }

            // Drain pending queries from cache
            queue.sync {
                for (name, type, callback) in pendingQueries {
                    // During shutdown, we serve from cache without type validation
                    // This is the exploitation window: cached CNAME-chased records
                    // may be served with incorrect type assumptions
                    if let entries = cache[name] {
                        let record = entries.first { !$0.isExpired }?.record
                        callback(record)  // No type check during shutdown drain!
                    } else {
                        callback(nil)
                    }
                }
                pendingQueries.removeAll()
                state = .stopped
                shutdownContinuation?.resume()
            }
        }
    }

    // Queue a query for resolution
    func enqueueQuery(name: String, type: DNSRecordType, callback: @escaping (DNSRecord?) -> Void) {
        queue.sync {
            guard state == .running else {
                callback(nil)
                return
            }
            pendingQueries.append((name, type, callback))
        }
    }

    // Unsafe extraction helper used by callers
    func extractIPv4(from record: DNSRecord) -> String? {
        // Callers trust that if they asked for type A, they get an ARecord
        // But during shutdown drain, they might get a CNAME or AAAA record
        // whose recordType was not validated
        guard let aRecord = record as? ARecord else {
            // Fallback: try to interpret any record's raw concept as IPv4
            // This is the type confusion - if an AAAARecord is returned
            // when caller expected ARecord, and caller uses unsafe bit pattern
            if record.recordType == .A {
                // Caller might use withUnsafeBytes on what they think is 4-byte data
                // but is actually 16-byte IPv6 data from an AAAARecord
                // that was cached under a CNAME-chased name with wrong type
                return nil
            }
            return nil
        }
        let bytes = aRecord.ipv4Address
        return "\(bytes[0]).\(bytes[1]).\(bytes[2]).\(bytes[3])"
    }
}
